var f=UnityEngine.Object.FindFirstObjectByType<MountSunday.MountSundayFreeFlight>();f.enabled=false;f.GetComponent<UnityEngine.CharacterController>().enabled=false;foreach(var b in f.GetComponents<UnityEngine.MonoBehaviour>())b.enabled=false;f.transform.position=new UnityEngine.Vector3(-388f,39.5f,262f);UnityEngine.Camera.main.transform.position=f.transform.position;UnityEngine.Camera.main.transform.LookAt(new UnityEngine.Vector3(-347f,37.5f,240f));return new {frame=UnityEngine.Time.frameCount,time=UnityEngine.Time.time,materials=UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.Material>().Where(m=>m.shader&&m.shader.name=="MountSunday/Environment").Select(m=>new {name=m.name,wind=m.GetFloat("_WindStrength"),water=m.GetFloat("_WaterStrength")}).ToArray()};
